public int lonelyInteger(int[] arr) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int x : arr) {
        count.merge(x, 1, Integer::sum);
    }
    for (Map.Entry<Integer, Integer> e : count.entrySet()) {
        if (e.getValue() == 1) {
            return e.getKey();
        }
    }
    return -1;   // unreachable given the guarantee
}

code.python:
def lonelyInteger(arr: list[int]) -> int:
    count: dict[int, int] = {}
    for x in arr:
        count[x] = count.get(x, 0) + 1
    for value, c in count.items():
        if c == 1:
            return value
    return -1   # unreachable given the guarantee

code.java:
public int lonelyInteger(int[] arr) {
    int result = 0;                 // XOR identity
    for (int x : arr) {
        result ^= x;                // twins cancel, loner survives
    }
    return result;
}

